}class Shape{
    constructor(vertices){
        this.vertices = vertices;
        this.color = "black";

        if(new.target === Shape){
            throw new TypeError("Cannot construct abstract instance directly of class 'Shape'");
        }
    }

    isPointInside(position){
		let isInside = false;
		for(let i=0; i < this.vertices.length; i++){
			let vertex = this.vertices[i];
			let normal = this.normals[i];

			let vertToPoint = Sub(position, vertex);
			let dot = vertToPoint.Dot(normal);

			if(dot > 0) return false;
			else isInside = true;
		}
		return isInside;
    }

    getDirectionOut(pos){
        let bestNormal = null;
        let smallest = -Number.MAX_VALUE;

		for(let i=0; i < this.vertices.length; i++){
			let vertex = this.vertices[i];
			let normal = this.normals[i];

			let vertToPoint = Sub(pos, vertex);
			let dot = vertToPoint.Dot(normal);

            if(dot >= 0){
                return null;
            }else if(dot > smallest){
                smallest = dot;
                bestNormal = normal.Cpy();
            }
        }

        if(!bestNormal){
            return null;
        }

        return Scale(bestNormal, smallest * -1);
    }

    moveBy(delta){
        for(let i=0; i < this.vertices.length;i++){
            this.vertices[i] = Add(this.vertices[i], delta);
        }
    }

    draw(){
        for(let i=1; i < this.vertices.length;i++){
            DrawUtils.drawLine(this.vertices[i-1], this.vertices[i], this.color,3);
        }
        DrawUtils.drawLine(this.vertices[this.vertices.length-1], this.vertices[0], this.color,3);
    }
}class Circle extends Shape{
    constructor(position, radius, color){
        super([]);
        this.position = position;
        this.radius = radius;
        this.color = color;
    }

    isPointInside(pos){
        let distance = Sub(pos, this.position).Length();
        return distance < this.radius;
    }

    getDirectionOut(pos){
        let direction = Sub(pos, this.position);
        if(direction.Length2() < this.radius * this.radius){
            let penetration = this.radius - direction.Length();
            direction.Normalize();
            direction = Scale(direction, penetration);
            return direction;
        }else{
            return null;
        }
    }


    moveBy(delta){
        this.position = Add(this.position, delta);
    }

    draw(){
        DrawUtils.strokePoint(this.position, this.radius, this.color,3);
