    drawOrientedCapsule(center, axis, normal, length, width, fill, stroke, alpha){
        let a = Add(center, Scale(axis, -length * 0.5));
        let b = Add(center, Scale(axis, length * 0.5));
        let r = width * 0.5;

        ctx.globalAlpha = alpha;
        ctx.beginPath();
        ctx.moveTo(a.x + normal.x * r, a.y + normal.y * r);
        ctx.lineTo(b.x + normal.x * r, b.y + normal.y * r);
        ctx.lineTo(b.x - normal.x * r, b.y - normal.y * r);
        ctx.lineTo(a.x - normal.x * r, a.y - normal.y * r);
        ctx.closePath();
        ctx.fillStyle = fill;
        ctx.strokeStyle = stroke;
        ctx.lineWidth = 3;
        ctx.fill();
        ctx.stroke();
        ctx.globalAlpha = 1;
    }
