    updateBottleFromPour(){
        let totalLength = this.bottle.neckLength + this.bottle.bodyLength;
        let axis = new Vector2(Math.cos(this.bottle.angle), Math.sin(this.bottle.angle));
        let mouth = Sub(this.bottle.center, Scale(axis, totalLength * 0.5));
        let mouthOut = Scale(axis, -1);
        let downward = Math.max(0, mouthOut.y);
        let tiltFlow = Math.max(0, (downward - 0.16) / 0.78);
        tiltFlow = Math.min(1, tiltFlow);

        let pourDir = Add(Scale(mouthOut, 1.35), new Vector2(0, 0.72));
        pourDir.Normalize();

        this.bottle.mouth = mouth;
        this.bottle.axis = axis;
        this.bottle.pourDir = pourDir;
        this.pourAmount = this.bottleVolumeL <= 0 ? 0 : this.smoothStep(tiltFlow);

        this.emitter.position = mouth;
        this.emitter.direction = pourDir;
        this.emitter.flowScale = this.pourAmount;
        this.emitter.size = 7 + this.emitter.flowScale * 8;
        this.emitter.amount = 5 + Math.round(this.emitter.flowScale * 8);
        this.emitter.velocity = 60 + this.emitter.flowScale * 46;
        this.emitter.spread = 0.035 + this.emitter.flowScale * 0.12;
    }

    bottleLocalToWorld(local){
        let axis = this.bottle.axis;
        let normal = axis.GetNormal();
        normal.Normalize();
        let bodyCenter = Add(this.bottle.mouth, Scale(axis, this.bottle.neckLength + this.bottle.bodyLength * 0.5));
        return Add(bodyCenter, Add(Scale(normal, local.x), Scale(axis, local.y)));
    }

    releaseBottleParticles(dt){
        if(this.pourAmount <= 0.02 || this.bottleParticles.length === 0 || this.particles.length >= this.MAX_PARTICLES){
            this.bottleVolumeL = this.bottleParticles.length * this.PARTICLE_LITERS;
            return 0;
        }

        let rate = 90 + this.pourAmount * 520;
        this.bottleReleaseDebt += rate * dt;
        let count = Math.min(
            Math.floor(this.bottleReleaseDebt),
            this.bottleParticles.length,
            this.MAX_PARTICLES - this.particles.length
        );

        if(count <= 0){
            this.bottleVolumeL = this.bottleParticles.length * this.PARTICLE_LITERS;
            return 0;
        }

        this.bottleReleaseDebt -= count;
        let released = 0;
        let dir = this.bottle.pourDir.Cpy();
        dir.Normalize();
        let normal = dir.GetNormal();
        normal.Normalize();

        this.bottleParticles.sort((a, b) => a.bottleLocal.y - b.bottleLocal.y);

        for(let i=0; i<count; i++){
            let particle = this.bottleParticles.shift();
            let spread = (i - count * 0.5) * 1.8 + (Math.random() - 0.5) * this.emitter.size;
            let pos = Add(this.bottle.mouth, Add(Scale(dir, 8 + Math.random() * 8), Scale(normal, spread)));
            particle.position = pos;
            particle.prevPosition = Sub(pos, Scale(dir, 3));
            particle.velocity = Add(Scale(dir, this.emitter.velocity * (0.88 + Math.random() * 0.2)), Scale(normal, (Math.random() - 0.5) * 11));
            particle.age = 0;
            particle.turbulence = 0.14 + Math.random() * 0.12;
            particle.foam = Math.random() * 0.08;
            particle.bottleLocal = null;
            this.particles.push(particle);
            released++;
        }

        this.bottleVolumeL = this.bottleParticles.length * this.PARTICLE_LITERS;
        return released;
    }

    smoothStep(t){
        return t * t * (3 - 2 * t);
    }

    getGlassBeerVolumeL(){
        let count = 0;
        for(let i=0; i<this.particles.length; i++){
            if(this.isInsideGlassInterior(this.particles[i].position)){
                count++;
            }
        }
        return count * this.PARTICLE_LITERS;
    }

    getGlassFill01(){
        return Math.max(0, Math.min(1, this.getGlassBeerVolumeL() / this.GLASS_CAPACITY_L));
    }

    getGlassSurfaceLocalY(){
        let fill = Math.max(0, Math.min(1.15, this.getGlassBeerVolumeL() / this.GLASS_CAPACITY_L));
        let bottom = this.glass.height * 0.5 - this.glass.wall;
        let usableHeight = this.glass.height * 0.78;
        return bottom - usableHeight * fill;
    }

