        pourDir.Normalize();

        this.bottle.mouth = mouth;
        this.bottle.axis = axis;
        this.bottle.pourDir = pourDir;
        this.pourAmount = this.bottleVolumeL <= 0 ? 0 : tiltFlow;

        this.emitter.position = mouth;
        this.emitter.direction = pourDir;
        this.emitter.flowScale = this.pourAmount;
        this.emitter.size = 4 + this.emitter.flowScale * 5;
        this.emitter.amount = 2 + Math.round(this.emitter.flowScale * 4);
        this.emitter.velocity = 3 + this.emitter.flowScale * 9;
        this.emitter.spread = 0.01 + this.emitter.flowScale * 0.035;
    }

    bottleLocalToWorld(local){
