        this.PLASTICITY = 0.9;
        this.SPRING_STIFFNESS = 1;

        this.BOTTLE_CAPACITY_L = 1.0;
        this.GLASS_CAPACITY_L = 0.5;
        this.PARTICLE_LITERS = 1 / 1800;
        this.bottleVolumeL = this.BOTTLE_CAPACITY_L;
        this.pourAmount = 0;
        this.foamSpawnDebt = 0;
        this.frame = 0;

        this.glass = {
            center: new Vector2(575, 520),
            angle: Math.PI / 4,
            topWidth: 205,
            bottomWidth: 126,
            height: 270,
            wall: 28
        };

        this.createGlass();

        this.fluidHashGrid = new FluidHashGrid(this.INTERACTION_RADIUS);
        this.fluidHashGrid.initialize(this.particles);

        this.bottle = {
            center: new Vector2(1010, 330),
            angle: Math.PI / 2,
            mouth: new Vector2(1010, 105),
            axis: new Vector2(0, 1),
            pourDir: new Vector2(0, -1),
            flowScale: 0,
            neckLength: 128,
            bodyLength: 322,
            neckWidth: 54,
            bodyWidth: 106
        };

        this.updateBottleFromPour();
        this.createBottleParticles();
        this.updateBottleVolume();
    }

    createBottleParticles(){
        let b = this.bottle;
        let total = Math.round(this.BOTTLE_CAPACITY_L / this.PARTICLE_LITERS);
        let spacing = 3.8;
        let rows = [];
        let liquidTop = -b.bodyLength * 0.5 - b.neckLength * 0.62;
        let liquidBottom = b.bodyLength * 0.5 - 13;

        for(let y=liquidBottom; y>=liquidTop; y-=spacing){
            let width = b.bodyWidth * 0.76;
            if(y < -b.bodyLength * 0.5){
                width = b.neckWidth * 0.48;
            }else if(y < -b.bodyLength * 0.5 + 52){
                let shoulder = Math.max(0, Math.min(1, (y + b.bodyLength * 0.5) / 52));
                width = b.neckWidth * 0.48 + (b.bodyWidth * 0.76 - b.neckWidth * 0.48) * shoulder;
            }

            let row = [];
            for(let x=-width * 0.5; x<=width * 0.5; x+=spacing){
                row.push(new Vector2(x + (Math.random() - 0.5) * 1.6, y + (Math.random() - 0.5) * 1.6));
            }
            rows.push(row);
        }

        let flat = [];
        for(let i=0; i<rows.length; i++){
            flat.push(...rows[i]);
        }

        for(let i=0; i<Math.min(total, flat.length); i++){
            let particle = new Particle(Vector2.Zero());
            particle.position = this.bottleLocalToWorld(flat[i]);
            particle.prevPosition = particle.position.Cpy();
            particle.foam = Math.random() * 0.04;
            this.particles.push(particle);
        }
    }

    setPourAmount(value){
        this.pourAmount = Math.max(0, Math.min(1, value));
        this.bottle.angle = Math.PI / 2 - this.pourAmount * Math.PI * 1.05;
        this.updateBottleFromPour();
    }

    setBottleCenter(position){
        let delta = Sub(position, this.bottle.center);
        this.moveBottleContents(delta);
        this.bottle.center = position.Cpy();
        this.updateBottleFromPour();
    }

    rotateBottle(deltaAngle){
        this.rotateBottleContents(deltaAngle);
        this.bottle.angle += deltaAngle;
        this.bottle.angle = Math.max(-Math.PI * 0.78, Math.min(Math.PI * 1.18, this.bottle.angle));
        this.updateBottleFromPour();
    }

    createGlass(){
        this.shapes = [];
