            targetCtx.arc(p.position.x, p.position.y - 2, r, 0, Math.PI * 2);
            targetCtx.strokeStyle = "rgba(255,250,235,0.90)";
            targetCtx.stroke();
        }

        targetCtx.restore();
        targetCtx.globalAlpha = 1;
    }

    draw(){
        this.drawGlass();
        this.drawBottle();
        this.drawMeters();
    }

    drawGlass(){
        let g = this.glass;
        let topY = -g.height * 0.5;
        let bottomY = g.height * 0.5;
        let rimA = this.glassLocalToWorld(new Vector2(-g.topWidth * 0.5, topY));
        let rimB = this.glassLocalToWorld(new Vector2(g.topWidth * 0.5, topY));
        let baseA = this.glassLocalToWorld(new Vector2(-g.bottomWidth * 0.5, bottomY));
        let baseB = this.glassLocalToWorld(new Vector2(g.bottomWidth * 0.5, bottomY));
        let capacityY = bottomY - g.height * 0.58;
        let capT = (capacityY + g.height * 0.5) / g.height;
        let capWidth = g.topWidth + (g.bottomWidth - g.topWidth) * capT;
        let capA = this.glassLocalToWorld(new Vector2(-capWidth * 0.5 + 18, capacityY));
        let capB = this.glassLocalToWorld(new Vector2(capWidth * 0.5 - 18, capacityY));

        ctx.save();
        ctx.lineJoin = "round";
        ctx.lineCap = "round";

        ctx.beginPath();
        ctx.moveTo(rimA.x, rimA.y);
        ctx.lineTo(baseA.x, baseA.y);
        ctx.lineTo(baseB.x, baseB.y);
        ctx.lineTo(rimB.x, rimB.y);
        ctx.strokeStyle = "rgba(225,245,255,0.74)";
        ctx.lineWidth = 8;
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(rimA.x, rimA.y);
        ctx.lineTo(rimB.x, rimB.y);
        ctx.strokeStyle = "rgba(255,255,255,0.94)";
        ctx.lineWidth = 5;
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(capA.x, capA.y);
        ctx.lineTo(capB.x, capB.y);
        ctx.strokeStyle = "rgba(255,255,255,0.32)";
        ctx.lineWidth = 2;
        ctx.stroke();

        let shineA = this.glassLocalToWorld(new Vector2(-g.topWidth * 0.28, topY + 26));
        let shineB = this.glassLocalToWorld(new Vector2(-g.bottomWidth * 0.18, bottomY - 44));
        DrawUtils.drawLine(shineA, shineB, "rgba(255,255,255,0.34)", 3);

        ctx.restore();
    }

    drawBottle(){
        let mouth = this.bottle.mouth;
        let axis = this.bottle.axis;
        let normal = axis.GetNormal();
        normal.Normalize();

        let neckLength = this.bottle.neckLength;
        let bodyLength = this.bottle.bodyLength;
        let neckWidth = this.bottle.neckWidth;
        let bodyWidth = this.bottle.bodyWidth;

        let neckCenter = Add(mouth, Scale(axis, neckLength * 0.5));
        let bodyCenter = Add(mouth, Scale(axis, neckLength + bodyLength * 0.5));

        ctx.save();
        ctx.lineJoin = "round";
        ctx.lineCap = "round";

        this.drawOrientedCapsule(bodyCenter, axis, normal, bodyLength, bodyWidth, "rgba(35,24,11,0.86)", "rgba(190,135,42,0.86)", 1);
        this.drawBottleReservoirParticles();
        this.drawOrientedCapsule(bodyCenter, axis, normal, bodyLength, bodyWidth, "rgba(65,42,14,0.28)", "rgba(245,181,68,0.84)", 1);
        this.drawOrientedCapsule(neckCenter, axis, normal, neckLength, neckWidth, "rgba(88,58,18,0.44)", "rgba(230,170,65,0.88)", 1);

        let capCenter = Add(mouth, Scale(axis, 5));
        this.drawOrientedCapsule(capCenter, axis, normal, 18, neckWidth + 7, "#d1aa48", "#ffe0a0", 1);

        let highlightStart = Add(bodyCenter, Add(Scale(normal, -bodyWidth * 0.28), Scale(axis, -bodyLength * 0.35)));
        let highlightEnd = Add(bodyCenter, Add(Scale(normal, -bodyWidth * 0.28), Scale(axis, bodyLength * 0.18)));
        DrawUtils.drawLine(highlightStart, highlightEnd, "rgba(255,226,141,0.42)", 6);

        ctx.restore();
    }

    drawBottleReservoirParticles(){
        ctx.save();
        ctx.globalAlpha = 0.72;
        ctx.fillStyle = "#f0a22a";

        let drawn = 0;
        for(let i=0; i<this.particles.length; i+=2){
            let p = this.particles[i];
            if(!p.inBottle || !this.isInsideBottleInterior(p.position, 2)){
                continue;
            }
            ctx.beginPath();
            ctx.arc(p.position.x, p.position.y, 3.0, 0, Math.PI * 2);
            ctx.fill();
            drawn++;
        }

        ctx.globalAlpha = 0.34;
        ctx.fillStyle = "#ffe083";
        for(let i=0; i<this.particles.length; i+=37){
            let p = this.particles[i];
            if(!p.inBottle || !this.isInsideBottleInterior(p.position, 2)){
                continue;
            }
            ctx.beginPath();
            ctx.arc(p.position.x - 1.5, p.position.y - 1.8, 1.5, 0, Math.PI * 2);
            ctx.fill();
        }

        ctx.restore();
    }

    drawMeters(){
        let x = 22;
        let y = 18;
        let w = 240;
        let bottleFill = Math.max(0, Math.min(1, this.bottleVolumeL / this.BOTTLE_CAPACITY_L));
        let glassFill = Math.max(0, Math.min(1.25, this.getGlassBeerVolumeL() / this.GLASS_CAPACITY_L));

        ctx.save();
        ctx.fillStyle = "rgba(18,15,12,0.74)";
        ctx.strokeStyle = "rgba(255,226,150,0.24)";
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.rect(x, y, w, 70);
        ctx.fill();
        ctx.stroke();

        this.drawMeterLine(x + 14, y + 18, w - 28, bottleFill, "#f2a42c", "Bottle 1.0L");
        this.drawMeterLine(x + 14, y + 46, w - 28, Math.min(1, glassFill), glassFill > 1 ? "#ffcf66" : "#f0b13f", "Glass 0.5L");
        ctx.restore();
    }

    drawMeterLine(x, y, width, fill, color, label){
        ctx.fillStyle = "rgba(255,255,255,0.10)";
        ctx.fillRect(x, y, width, 9);
        ctx.fillStyle = color;
        ctx.fillRect(x, y, width * fill, 9);
        ctx.fillStyle = "rgba(255,245,220,0.82)";
        ctx.font = "12px Arial";
        ctx.fillText(label, x, y - 4);
    }

    drawOrientedCapsule(center, axis, normal, length, width, fill, stroke, alpha){
        let a = Add(center, Scale(axis, -length * 0.5));
        let b = Add(center, Scale(axis, length * 0.5));
        let r = width * 0.5;

        ctx.globalAlpha = alpha;
        ctx.beginPath();
        ctx.moveTo(a.x + normal.x * r, a.y + normal.y * r);
        ctx.lineTo(b.x + normal.x * r, b.y + normal.y * r);
        ctx.lineTo(b.x - normal.x * r, b.y - normal.y * r);
        ctx.lineTo(a.x - normal.x * r, a.y - normal.y * r);
        ctx.closePath();
        ctx.fillStyle = fill;
        ctx.strokeStyle = stroke;
        ctx.lineWidth = 3;
        ctx.fill();
        ctx.stroke();
        ctx.globalAlpha = 1;
    }
}

