            correction = Scale(correction, 1.35);
            this.bottle.center = Add(this.bottle.center, correction);
            this.moveBottleContents(correction);
            this.updateBottleFromPour();
        }
    }

    smoothStep(t){
        return t * t * (3 - 2 * t);
    }

    getGlassBeerVolumeL(){
        let count = 0;
        for(let i=0; i<this.particles.length; i++){
            if(this.isInsideGlassInterior(this.particles[i].position)){
                count++;
            }
        }
        return count * this.PARTICLE_LITERS;
    }

    getGlassFill01(){
        return Math.max(0, Math.min(1, this.getGlassBeerVolumeL() / this.GLASS_CAPACITY_L));
    }

    getGlassSurfaceLocalY(){
        let fill = Math.max(0, Math.min(1.15, this.getGlassBeerVolumeL() / this.GLASS_CAPACITY_L));
        let bottom = this.glass.height * 0.5 - this.glass.wall;
        let usableHeight = this.glass.height * 0.78;
        return bottom - usableHeight * fill;
    }

    neighbourSearch(){
        this.fluidHashGrid.clearGrid();
        this.fluidHashGrid.mapParticleToCell();
    }

    applyGravity(dt){
        for(let i=0; i< this.particles.length; i++){
            this.particles[i].velocity = Add(this.particles[i].velocity, Scale(this.GRAVITY, dt));
        }
    }

    applyBeerForces(dt){
        let glassVolume = this.getGlassBeerVolumeL();
        let overflow = Math.max(0, (glassVolume - this.GLASS_CAPACITY_L) / this.GLASS_CAPACITY_L);
        let rimOut = new Vector2(-0.8, -0.2);
        rimOut.Normalize();

        for(let i=0; i<this.particles.length; i++){
            let particle = this.particles[i];
            if(this.isInsideGlassInterior(particle.position)){
                particle.velocity = Scale(particle.velocity, 0.999);
                particle.velocity.x += Math.sin((particle.age * 4 + i) * 0.31) * 0.018 * this.pourAmount;

                if(overflow > 0){
                    let local = this.worldToGlassLocal(particle.position);
                    let surfaceBias = Math.max(0, 1 - (local.y + this.glass.height * 0.5) / (this.glass.height * 0.42));
                    particle.velocity = Add(particle.velocity, Scale(rimOut, overflow * surfaceBias * dt * 7.5));
                }
            }
        }
    }

    predictPositions(dt){
        for(let i=0; i< this.particles.length; i++){
            this.particles[i].prevPosition = this.particles[i].position.Cpy();
            let positionDelta = Scale(this.particles[i].velocity, dt * this.VELOCITY_DAMPING);
            this.particles[i].position = Add(this.particles[i].position, positionDelta);
        }
    }

    computeNextVelocity(dt){
        for(let i=0; i< this.particles.length; i++){
            let velocity = Scale(Sub(this.particles[i].position, this.particles[i].prevPosition), 1.0 / dt);
            this.particles[i].velocity = velocity;
        }
    }

    handleOneWayCoupling(dt){
        for(let i=0; i< this.particles.length; i++){
            let particle = this.particles[i];
            for(let j=0; j<this.shapes.length;j++){
                let dir = this.shapes[j].getDirectionOut(particle.position);
                if(dir != null){
                    let speed = particle.velocity.Length();
                    let impact = Math.min(1, Math.max(0, speed - 9) / 48);
                    particle.position = Add(particle.position, dir);
                    if(speed > 0.0001){
                        particle.prevPosition = Sub(particle.position, Scale(particle.velocity, dt * 0.82));
                    }
                    particle.turbulence = Math.min(1, particle.turbulence + impact * 0.42);
                    particle.foam = Math.min(1, particle.foam + impact * 0.16);

                    if(this.isInsideGlassInterior(particle.position) && impact > 0.12){
                        this.createFoamBurst(particle.position, impact * (0.7 + this.pourAmount));
                    }
                }
            }
        }
    }

    constrainGlassCrossing(dt){
        let g = this.glass;
        let top = -g.height * 0.5;
        let bottom = g.height * 0.5 - g.wall;

        for(let i=0; i<this.particles.length; i++){
            let p = this.particles[i];
            let prevLocal = this.worldToGlassLocal(p.prevPosition);
            let wasInside = prevLocal.x > -this.getGlassInteriorHalfWidth(prevLocal.y) &&
                prevLocal.x < this.getGlassInteriorHalfWidth(prevLocal.y) &&
                prevLocal.y > top &&
                prevLocal.y < bottom;

            if(!wasInside){
                continue;
            }

            let local = this.worldToGlassLocal(p.position);
            let clamped = false;

            if(local.y > bottom){
                local.y = bottom;
                clamped = true;
            }

            if(local.y > top + 4 && local.y < bottom + 8){
                let halfWidth = this.getGlassInteriorHalfWidth(local.y);
                if(local.x < -halfWidth){
                    local.x = -halfWidth;
                    clamped = true;
                }else if(local.x > halfWidth){
                    local.x = halfWidth;
                    clamped = true;
                }
            }

            if(clamped){
                let velocity = p.velocity.Cpy();
                p.position = this.glassLocalToWorld(local);
                p.prevPosition = Sub(p.position, Scale(velocity, dt * 0.28));
                p.velocity = Scale(velocity, 0.58);
                p.turbulence = Math.min(1, p.turbulence + 0.08);
            }
        }
    }

    ageBeerAndCreateFoam(dt){
        let candidates = [];
        let glassVolume = this.getGlassBeerVolumeL();
        let surfaceY = this.getGlassSurfaceLocalY();

        for(let i=0; i<this.particles.length; i++){
            let p = this.particles[i];
            p.age += dt;
            p.turbulence *= 0.972;
            p.foam *= 0.992;

            if(this.isInsideGlassInterior(p.position)){
                let speed = p.velocity.Length();
                let local = this.worldToGlassLocal(p.position);
                let nearSurface = Math.abs(local.y - surfaceY) < 34 || local.y < surfaceY + 22;

                if(speed > 18 || p.turbulence > 0.16){
                    p.foam = Math.min(1, p.foam + 0.008 + p.turbulence * 0.01);
                    if(candidates.length < 110 && Math.random() < 0.055 + this.pourAmount * 0.035){
                        candidates.push(p);
                    }
                }

                if(nearSurface && glassVolume > 0.035){
                    p.foam = Math.min(1, p.foam + 0.005 + this.pourAmount * 0.006);
                    if(candidates.length < 140 && Math.random() < 0.035 + p.foam * 0.03){
                        candidates.push(p);
                    }
                }
            }
        }

        this.foamSpawnDebt += Math.max(0, this.pourAmount - 0.18) * 0.42;
        while(this.foamSpawnDebt > 1 && candidates.length > 0){
            this.foamSpawnDebt -= 1;
            let candidate = candidates[Math.floor(Math.random() * candidates.length)];
            this.createFoamBurst(candidate.position, 0.5 + this.pourAmount * 0.9);
        }
    }

    createFoamBurst(position, intensity){
        if(this.foamParticles.length >= this.MAX_FOAM_PARTICLES){
            return;
        }

        let amount = Math.max(1, Math.floor(1 + intensity * 5));
        for(let i=0; i<amount && this.foamParticles.length < this.MAX_FOAM_PARTICLES; i++){
            let angle = Math.random() * Math.PI * 2;
            let radius = Math.random() * 13 * intensity;
            let pos = Add(position, new Vector2(Math.cos(angle) * radius, Math.sin(angle) * radius));
            let vel = new Vector2(
                (Math.random() - 0.5) * (12 + intensity * 9),
                -8 - Math.random() * (13 + intensity * 8)
            );
            let bubbleRadius = 3.5 + Math.random() * 8 + intensity * 3;
            let life = 0.55 + Math.random() * 0.75 + intensity * 0.7;
            this.foamParticles.push(new FoamParticle(pos, vel, bubbleRadius, life));
        }
    }

    updateFoamParticles(dt){
        for(let i=this.foamParticles.length - 1; i>=0; i--){
            let foam = this.foamParticles[i];
            foam.life -= dt * 0.11;

            if(foam.life <= 0){
                this.foamParticles.splice(i, 1);
                continue;
            }

            foam.prevPosition = foam.position.Cpy();
            foam.velocity.y -= 0.18 * dt;
            foam.velocity.x += Math.sin(foam.seed + foam.life * 8.0) * 0.04;
            foam.velocity = Scale(foam.velocity, 0.982);
            foam.position = Add(foam.position, Scale(foam.velocity, dt));

            for(let j=0; j<this.shapes.length; j++){
                let dir = this.shapes[j].getDirectionOut(foam.position);
                if(dir != null){
